}

.ask-skel-line.is-short {
  width: 62%;
}

.ask-source.is-skel {
  min-height: 3.4rem;
  animation: ask-pulse 1.2s ease-in-out infinite;
}

.ask-jump {
  display: inline-flex;
  align-items: center;
  min-height: 2.5rem;
