  const profile = intel.profile;
  const touched = intel.thesis.matches.map((item) => item.label.toLowerCase());
  const product = profile.product ? profile.product.replace(/\.$/, "") : profile.company;
  const where = touched.length
    ? `It fits the thesis on ${touched.join(", ")}.`
    : "It does not yet sit on a preferred thesis filter.";
  return `${product}. ${where} ${profile.sector}. ${profile.stage}, ${profile.geography}.`;
}

