import type { Flag } from "@/lib/diligence/types";
import { STAGE_LABELS, normalizeStage, type DealIntelligence } from "@/lib/intelligence/types";
import { headerScores, plainAction } from "@/lib/intelligence/viewStory";

type Props = {
  intel: DealIntelligence;
  flags: Flag[];
  waiting?: string;
};

export function DealHeader({ intel, flags, waiting }: Props) {
  const stage = normalizeStage(intel.stage);
  const scores = headerScores(intel, flags);

  return (
    <div className="deal-head">
      <p className="deal-head-stage">
        {STAGE_LABELS[stage]}
        {waiting ? ` · ${waiting}` : ""}
      </p>
      <h1>{intel.profile.company}</h1>
      <p className="deal-head-next">{plainAction(intel.nextAction.title)}</p>
      <ul className="score-plain">
        {scores.map((row) => (
          <li key={row.key}>
            <p>{row.label}</p>
            <p>{row.value ?? "—"}</p>
            <p>{row.note}</p>
          </li>
        ))}
      </ul>
    </div>
  );
}

import type { DealIntelligence } from "@/lib/intelligence/types";
import { thesisBrief, thesisChecks } from "@/lib/intelligence/viewStory";
import { Note, Section } from "./ui";

export function ThesisTab({ intel }: { intel: DealIntelligence }) {
  const score = intel.thesis.score;
  const checks = thesisChecks(intel);
  return (
    <div>
      <Section title="Thesis fit">
        <p className="font-serif text-[2.1rem] leading-none">{score ?? "—"}</p>
        <p className="mt-4 max-w-[38rem] text-[1.05rem] leading-7">{thesisBrief(intel)}</p>
      </Section>
      <Section title="Shared with the thesis">
        {checks.length ? (
          <ul className="thesis-checks">
            {checks.map((item) => (
              <li key={item.label}>
                <label>
                  <input type="checkbox" checked={item.on} readOnly />
                  <span>
                    <strong>{item.label}</strong>
