export type SearchHit = {
  title: string;
  url: string;
  description: string;
};

function apiKey() {
  return process.env.FIRECRAWL_API_KEY?.trim() || "";
}

export function firecrawlReady() {
  return Boolean(apiKey());
}

export async function firecrawlSearch(query: string, limit = 5): Promise<SearchHit[]> {
  if (!apiKey()) {
    throw new Error("Add FIRECRAWL_API_KEY to search the open web.");
  }
  const res = await fetch("https://api.firecrawl.dev/v1/search", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey()}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ query, limit }),
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(text.slice(0, 200) || `Firecrawl search failed (${res.status})`);
  }
  const data = (await res.json()) as {
    data?: { title?: string; url?: string; description?: string; markdown?: string }[];
    web?: { title?: string; url?: string; description?: string }[];
  };
  const rows = data.data ?? data.web ?? [];
  return rows
    .map((row) => ({
      title: row.title || row.url || "Result",
      url: row.url || "",
      description: row.description || "",
    }))
    .filter((row) => row.url);
}

import { NextResponse } from "next/server";
import { firecrawlReady, firecrawlSearch } from "@/lib/diligence/firecrawl";
import { loadDeal } from "@/lib/diligence/store";

export async function POST(_request: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const deal = await loadDeal(id);
    if (!deal?.intelligence) return NextResponse.json({ error: "Deal not found" }, { status: 404 });
    if (!firecrawlReady()) {
      return NextResponse.json({ error: "Add FIRECRAWL_API_KEY to run founder search." }, { status: 400 });
    }
    const names = deal.intelligence.profile.founders;
    const company = deal.intelligence.profile.company;
    const people = [];
    for (const name of names) {
      const hits = await firecrawlSearch(`${name} ${company} LinkedIn founder`, 4);
      people.push({
        name,
        query: `${name} ${company}`,
        hits,
        spikes: deal.intelligence.people
          .filter((note) => note.claim.toLowerCase().includes(name.split(" ")[0]!.toLowerCase()))
          .map((note) => note.assessment),
      });
    }
    return NextResponse.json({ people, at: new Date().toISOString() });
  } catch (error) {
    return NextResponse.json({ error: (error as Error).message }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { firecrawlReady, firecrawlSearch } from "@/lib/diligence/firecrawl";
