    if (!deal?.intelligence) return NextResponse.json({ error: "Deal not found" }, { status: 404 });
    if (!firecrawlReady()) {
      return NextResponse.json({ error: "Add FIRECRAWL_API_KEY to run market search." }, { status: 400 });
    }
    const { sector, product, company } = deal.intelligence.profile;
    const [tam, competitors, space] = await Promise.all([
      firecrawlSearch(`${sector} total addressable market size ${product}`, 4),
      firecrawlSearch(`${product} competitors ${sector}`, 4),
      firecrawlSearch(`${sector} warehouse automation open market whitespace 2026`, 3),
    ]);
    const deckTam = deal.flags.find((flag) => flag.metric === "tam");
    return NextResponse.json({
      company,
      sector,
      deckTam: deckTam?.deckValue ?? deckTam?.comment,
      tam,
      competitors,
      space,
      at: new Date().toISOString(),
    });
  } catch (error) {
    return NextResponse.json({ error: (error as Error).message }, { status: 500 });
  }
}

