"use client";

import { useState, useTransition } from "react";
import { readJson } from "@/lib/http";
import type { DealIntelligence } from "@/lib/intelligence/types";
import { WorldTab } from "./WorldTab";
import { Note, Section } from "./ui";

type Hit = { title: string; url: string; description: string };

export function MarketPane({ dealId, intel }: { dealId: string; intel: DealIntelligence }) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [pack, setPack] = useState<{
    deckTam?: string;
    tam: Hit[];
    competitors: Hit[];
    space: Hit[];
  } | null>(null);
  const tamClaim = intel.claims.find((item) => item.metric === "tam");

  function search() {
    setError(null);
    start(async () => {
      const res = await fetch(`/api/deals/${dealId}/research/market`, { method: "POST" });
      const data = await readJson(res);
      if (!res.ok) {
        setError(typeof data.error === "string" ? data.error : "Could not search the market.");
        return;
      }
      setPack({
        deckTam: typeof data.deckTam === "string" ? data.deckTam : undefined,
        tam: asHits(data.tam),
        competitors: asHits(data.competitors),
        space: asHits(data.space),
      });
    });
  }

  return (
    <div>
      <Section title="Total Market Size">
        <p className="text-[1.05rem] leading-7">
          {tamClaim?.managementValue || pack?.deckTam || "No Total Market Size on the deck yet."}
        </p>
        {tamClaim?.recomputedValue ? (
          <p className="mt-2 text-mute">From the files: {tamClaim.recomputedValue}.</p>
        ) : null}
        <button type="button" className="ask-jump mt-5" disabled={pending} onClick={search}>
          {pending ? "Searching…" : "Run market search"}
        </button>
        {error ? <p className="mt-3 text-flag-red">{error}</p> : null}
      </Section>

      {pack ? (
        <>
          <HitList title="Market size sources" hits={pack.tam} />
          <HitList title="Open space" hits={pack.space} />
          <HitList title="Competitors" hits={pack.competitors} />
        </>
      ) : (
        <Section title="External checks">
          <Note>Run the search to pull Total Market Size, whitespace, and competitors from the open web.</Note>
        </Section>
      )}

      <WorldTab intel={intel} />
    </div>
  );
}

function HitList({ title, hits }: { title: string; hits: Hit[] }) {
  if (!hits.length) return null;
  return (
    <Section title={title}>
      <ul className="prose-list">
        {hits.map((hit) => (
          <li key={hit.url}>
            <a href={hit.url} target="_blank" rel="noreferrer">
              {hit.title}
            </a>
            {hit.description ? <span className="block text-mute">{hit.description}</span> : null}
          </li>
        ))}
      </ul>
    </Section>
  );
}

function asHits(raw: unknown): Hit[] {
  if (!Array.isArray(raw)) return [];
  return raw
    .map((item) => {
      if (!item || typeof item !== "object") return null;
      const row = item as Record<string, unknown>;
      if (typeof row.url !== "string") return null;
      return {
        title: typeof row.title === "string" ? row.title : row.url,
        url: row.url,
        description: typeof row.description === "string" ? row.description : "",
      };
    })
    .filter((item): item is Hit => Boolean(item));
}

