import type { Deal } from "./types";
import { firecrawlSearch } from "./firecrawl";
import type { FounderResearch, MarketResearch } from "../intelligence/types";

export async function researchFounders(deal: Deal): Promise<FounderResearch[]> {
  const intel = deal.intelligence;
  if (!intel) return [];
  const company = intel.profile.company;
  const names = intel.profile.founders.length ? intel.profile.founders : [company];
  const people: FounderResearch[] = [];
  for (const name of names) {
    const hits = await firecrawlSearch(`${name} LinkedIn founder`, 4);
    people.push({
      name,
      hits,
      spikes: intel.people
        .filter((note) => note.claim.toLowerCase().includes(name.split(" ")[0]!.toLowerCase()))
        .map((note) => note.assessment),
    });
  }
  return people;
}

export async function researchMarket(deal: Deal): Promise<MarketResearch> {
  const intel = deal.intelligence;
  if (!intel) {
    return { tam: [], competitors: [], space: [], at: new Date().toISOString() };
  }
  const { sector, product } = intel.profile;
  const [tam, competitors, space] = await Promise.all([
    firecrawlSearch(`${sector} total addressable market size ${product}`, 4),
    firecrawlSearch(`${product} competitors ${sector}`, 4),
    firecrawlSearch(`${sector} ${product} market whitespace open competitors`, 3),
  ]);
  const deckTam = deal.flags.find((flag) => flag.metric === "tam");
  return {
    deckTam: deckTam?.deckValue ?? deckTam?.comment,
    tam,
    competitors,
    space,
    at: new Date().toISOString(),
  };
}

