  const scores = [...el.querySelectorAll(".score-val")].map((n) => ({
    text: n.textContent,
    color: getComputedStyle(n).color,
    cls: n.className,
    x: Math.round(n.getBoundingClientRect().x),
  }));
  return { cols: cs.gridTemplateColumns, scores, name: el.querySelector(".pipe-name")?.textContent };
});
const dealPage = await page.goto("http://127.0.0.1:3000/deals/northstar-robotics", { waitUntil: "networkidle" });
const header = await page.locator(".score-plain .score-val").evaluateAll((nodes) =>
  nodes.map((n) => ({ text: n.textContent, cls: n.className, color: getComputedStyle(n).color })),
);
if (!/Thesis/.test(head) || !/Conviction/.test(head)) throw new Error(`head ${head}`);
if (first.scores.length !== 4) throw new Error("need 4 scores");
if (!first.scores.every((s) => /is-(good|mid|weak|empty)/.test(s.cls))) throw new Error(JSON.stringify(first.scores));
