import type { Deal } from "./types";
import { firecrawlSearch, type SearchHit } from "./firecrawl";
import { chat } from "./llm";
import type { FounderResearch, FounderSpike, MarketResearch, ResearchHit } from "../intelligence/types";

export async function researchFounders(deal: Deal): Promise<FounderResearch[]> {
  const intel = deal.intelligence;
  if (!intel) return [];
  const names = intel.profile.founders.length ? intel.profile.founders : [intel.profile.company];
  const people: FounderResearch[] = [];
  for (const name of names) {
    const hits = await searchFounderHits(name, intel.profile.company, intel.profile.sector);
    people.push(await assessFounder(name, intel.profile.company, intel.profile.sector, hits));
  }
  return people;
}

export async function assessStoredFounders(deal: Deal): Promise<FounderResearch[]> {
  const intel = deal.intelligence;
  if (!intel) return [];
  const stored = intel.research?.founders ?? [];
  const names = intel.profile.founders.length ? intel.profile.founders : [intel.profile.company];
  const people: FounderResearch[] = [];
  for (const name of names) {
    const prior = stored.find((item) => item.name === name);
    const hits = prior?.hits?.length
      ? prior.hits
      : await searchFounderHits(name, intel.profile.company, intel.profile.sector);
    people.push(await assessFounder(name, intel.profile.company, intel.profile.sector, hits));
  }
  return people;
}

async function searchFounderHits(name: string, company: string, sector: string): Promise<ResearchHit[]> {
  const first = await firecrawlSearch(`${name} LinkedIn founder`, 5);
  const cleaned = preferUseful(first, name, sector, company);
  if (cleaned.length >= 2) return cleaned.slice(0, 4);
  const extra = await firecrawlSearch(`${name} ${sector} founder LinkedIn`, 4);
  return preferUseful([...cleaned, ...extra], name, sector, company).slice(0, 4);
}

function preferUseful(hits: SearchHit[], name: string, sector: string, company: string): ResearchHit[] {
  const first = name.split(" ")[0]?.toLowerCase() ?? "";
  const keys = `${sector} ${company}`
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((word) => word.length > 3);
  const scored = hits
    .filter((hit) => hit.url && !/\/pub\/dir\/|profiles -/i.test(`${hit.title} ${hit.url}`))
    .map((hit) => {
      const blob = `${hit.title} ${hit.description}`.toLowerCase();
      let score = 0;
      if (blob.includes(first)) score += 2;
      if (/linkedin\.com\/in\//i.test(hit.url)) score += 3;
      if (keys.some((key) => blob.includes(key))) score += 2;
      return { hit, score };
    })
    .sort((a, b) => b.score - a.score);
  const seen = new Set<string>();
  return scored
    .map((row) => row.hit)
    .filter((hit) => {
      if (seen.has(hit.url)) return false;
      seen.add(hit.url);
      return true;
    });
}

async function assessFounder(
  name: string,
  company: string,
  sector: string,
  hits: ResearchHit[],
): Promise<FounderResearch> {
  const sources = hits
    .map(
      (hit, i) =>
        `${i + 1}. ${hit.title}\n${hit.url}\n${hit.description.slice(0, 500)}`,
    )
    .join("\n\n");
  const raw = sources
    ? await chat(
        [
          {
            role: "system",
            content:
              "You write short founder diligence for a venture partner. Use only the sources. Do not invent employers, degrees, or dates. If the public record looks like a different person than this company, say so. Return JSON only.",
          },
          {
            role: "user",
            content: `Company: ${company}\nSector: ${sector}\nFounder: ${name}\n\nSources:\n${sources}\n\nJSON shape:\n{"summary":"2-3 sentences on who they are, the spike, and what it means for this deal.","spikes":[{"title":"short label","detail":"one sentence with the evidence"}]}`,
          },
        ],
        { maxTokens: 500 },
      )
    : "";
  const parsed = readAssessment(raw);
  return {
    name,
    summary: parsed?.summary || fallbackSummary(name, company, hits),
    spikes: parsed?.spikes?.length ? parsed.spikes.slice(0, 4) : fallbackSpikes(hits),
    hits,
  };
}

function readAssessment(raw: string): { summary?: string; spikes?: FounderSpike[] } | null {
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");
  if (start < 0 || end <= start) return null;
  try {
    const data = JSON.parse(raw.slice(start, end + 1)) as {
      summary?: unknown;
      spikes?: unknown;
    };
    const spikes = Array.isArray(data.spikes)
      ? data.spikes
          .map((item) => {
            if (!item || typeof item !== "object") return null;
            const row = item as Record<string, unknown>;
            if (typeof row.title !== "string" || typeof row.detail !== "string") return null;
            return { title: row.title.trim(), detail: row.detail.trim() };
          })
          .filter((item): item is FounderSpike => Boolean(item?.title && item.detail))
      : [];
    return {
      summary: typeof data.summary === "string" ? data.summary.trim() : undefined,
      spikes,
    };
  } catch {
    return null;
  }
}

function fallbackSummary(name: string, company: string, hits: ResearchHit[]): string {
  const lead = hits[0];
  if (!lead) return `${name} is named on ${company}. No public history is attached yet.`;
  const clip = lead.description.replace(/\s+/g, " ").slice(0, 280);
  return clip ? `${name}. ${clip}` : `${name} appears in public records as ${lead.title}.`;
}

function fallbackSpikes(hits: ResearchHit[]): FounderSpike[] {
  return hits.slice(0, 2).map((hit) => ({
    title: hit.title.split(/[-|–]/)[0]?.trim() || "Public record",
    detail: (hit.description || hit.title).replace(/\s+/g, " ").slice(0, 180),
  }));
}

export async function researchMarket(deal: Deal): Promise<MarketResearch> {
  const intel = deal.intelligence;
  if (!intel) {
    return { tam: [], competitors: [], space: [], at: new Date().toISOString() };
  }
  const { sector, product } = intel.profile;
  const tam = await firecrawlSearch(`${sector} total addressable market size ${product}`, 4);
  const competitors = await firecrawlSearch(`${product} competitors ${sector}`, 4);
  const space = await firecrawlSearch(`${sector} ${product} market whitespace open competitors`, 3);
  const deckTam = deal.flags.find((flag) => flag.metric === "tam");
  return {
    deckTam: deckTam?.deckValue ?? deckTam?.comment,
    tam,
    competitors,
    space,
    at: new Date().toISOString(),
  };
}

"use client";

import { useState, useTransition } from "react";
import { readJson } from "@/lib/http";
import type { DealIntelligence, FounderResearch, FounderSpike, ResearchHit } from "@/lib/intelligence/types";
import { Note, Section } from "./ui";

export function FounderPane({ dealId, intel }: { dealId: string; intel: DealIntelligence }) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [people, setPeople] = useState<FounderResearch[] | null>(asPeople(intel.research?.founders));

  function search() {
    setError(null);
    start(async () => {
      const res = await fetch(`/api/deals/${dealId}/research/founder`, { method: "POST" });
      const data = await readJson(res);
      if (!res.ok) {
        setError(typeof data.error === "string" ? data.error : "Could not search founders.");
        return;
      }
      setPeople(asPeople(data.people));
    });
  }

  return (
    <div>
      <Section title="Founder diligence">
        <Note>
          Public history on each named founder — the spike, then the sources. Unusual backgrounds stay in
          evaluation.
        </Note>
        <button type="button" className="desk-btn mt-5" disabled={pending} onClick={search}>
          {pending ? "Reading public history…" : people?.length ? "Refresh founder research" : "Search LinkedIn and public history"}
        </button>
        {error ? <p className="mt-3 text-flag-red">{error}</p> : null}
      </Section>

      {people?.map((person) => (
        <Section key={person.name} title={person.name}>
          <p className="founder-summary">{person.summary}</p>
          {person.spikes.length ? (
            <div className="founder-spikes">
              <h3>Spikes of excellence</h3>
              <ul>
                {person.spikes.map((spike) => (
                  <li key={spike.title}>
                    <strong>{spike.title}</strong>
                    {spike.detail}
                  </li>
                ))}
              </ul>
            </div>
          ) : null}
          {person.hits.length ? (
            <div className="founder-cites">
              <h3>Sources</h3>
              <ol>
                {person.hits.map((hit, index) => (
                  <li key={hit.url}>
                    <a href={hit.url} target="_blank" rel="noreferrer">
                      [{index + 1}] {citeLabel(hit)}
                    </a>
                  </li>
                ))}
              </ol>
            </div>
          ) : null}
        </Section>
      ))}
    </div>
  );
}

function asPeople(raw: unknown): FounderResearch[] | null {
  if (!Array.isArray(raw) || !raw.length) return null;
  const people = raw
    .map((item) => {
      if (!item || typeof item !== "object") return null;
      const row = item as Record<string, unknown>;
      if (typeof row.name !== "string") return null;
      return {
        name: row.name,
        summary: typeof row.summary === "string" ? row.summary : "",
        spikes: asSpikes(row.spikes),
        hits: asHits(row.hits),
      };
    })
    .filter((item): item is FounderResearch => Boolean(item));
  return people.length ? people : null;
}

function asSpikes(raw: unknown): FounderSpike[] {
  if (!Array.isArray(raw)) return [];
  return raw
    .map((item) => {
      if (typeof item === "string" && item.trim()) return { title: "Note", detail: item.trim() };
      if (!item || typeof item !== "object") return null;
      const row = item as Record<string, unknown>;
      if (typeof row.title !== "string" || typeof row.detail !== "string") return null;
      return { title: row.title, detail: row.detail };
    })
    .filter((item): item is FounderSpike => Boolean(item));
}

function asHits(raw: unknown): ResearchHit[] {
  if (!Array.isArray(raw)) return [];
  return raw
    .map((item) => {
      if (!item || typeof item !== "object") return null;
      const row = item as Record<string, unknown>;
      if (typeof row.url !== "string") return null;
      return {
        title: typeof row.title === "string" ? row.title : row.url,
        url: row.url,
        description: typeof row.description === "string" ? row.description : "",
      };
    })
    .filter((item): item is ResearchHit => Boolean(item));
}

function citeLabel(hit: ResearchHit): string {
  return hit.title.replace(/\s*[|–-]\s*LinkedIn\s*$/i, "").trim() || hit.url;
}

