export async function firecrawlScrape(url: string): Promise<string> {
  if (!apiKey()) {
    throw new Error("Add FIRECRAWL_API_KEY to read a page.");
  }
  let res: Response | undefined;
  let text = "";
  for (let attempt = 0; attempt < 4; attempt++) {
    res = await fetch("https://api.firecrawl.dev/v2/scrape", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey()}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        url,
        formats: ["markdown"],
        onlyMainContent: true,
      }),
    });
    if (res.ok) break;
    text = await res.text();
    const wait = /retry after (\d+)/i.exec(text)?.[1];
    if (res.status !== 429 || attempt === 3) {
      throw new Error(text.slice(0, 200) || `Firecrawl scrape failed (${res.status})`);
    }
    await new Promise((resolve) => setTimeout(resolve, (Number(wait) || 20) * 1000));
  }
  if (!res?.ok) {
    throw new Error(text.slice(0, 200) || "Firecrawl scrape failed");
  }
  const data = (await res.json()) as {
    data?: { markdown?: string; content?: string };
    markdown?: string;
  };
  return (data.data?.markdown || data.data?.content || data.markdown || "").trim();
}

