      hits,
    };
  }
  const sources = hits
    .map((hit, i) => `${i + 1}. ${hit.title}\n${hit.url}\n${hit.description.slice(0, 1800)}`)
    .join("\n\n");
  const parsed = await requireJson<{ summary: string; spikes: FounderSpike[] }>(
