async function firecrawlPost(path: string, body: unknown): Promise<unknown> {
  if (!apiKey()) {
    throw new Error("Add FIRECRAWL_API_KEY to search the open web.");
  }
  let res: Response | undefined;
  let text = "";
  for (let attempt = 0; attempt < 4; attempt++) {
    res = await fetch(`https://api.firecrawl.dev/v2${path}`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey()}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    });
    if (res.ok) break;
    text = await res.text();
    const wait = /retry after (\d+)/i.exec(text)?.[1];
    if (res.status !== 429 || attempt === 3) {
      throw new Error(text.slice(0, 200) || `Firecrawl ${path} failed (${res.status})`);
    }
    await new Promise((resolve) => setTimeout(resolve, (Number(wait) || 20) * 1000));
  }
  if (!res?.ok) {
    throw new Error(text.slice(0, 200) || `Firecrawl ${path} failed`);
  }
  return res.json();
}

export async function firecrawlSearch(query: string, limit = 5): Promise<SearchHit[]> {
  const data = (await firecrawlPost("/search", { query, limit })) as {
    data?:
      | { title?: string; url?: string; description?: string; snippet?: string }[]
      | {
          web?: { title?: string; url?: string; description?: string; snippet?: string }[];
        };
    web?: { title?: string; url?: string; description?: string; snippet?: string }[];
  };
  const rows = Array.isArray(data.data)
    ? data.data
    : (data.data && "web" in data.data ? data.data.web : undefined) ?? data.web ?? [];
  return rows
    .map((row) => ({
      title: row.title || row.url || "Result",
      url: row.url || "",
      description: row.description || row.snippet || "",
    }))
    .filter((row) => row.url);
}

export async function firecrawlImageSearch(query: string, limit = 6): Promise<string[]> {
  const data = (await firecrawlPost("/search", {
    query,
    limit,
    sources: ["images"],
  })) as {
    data?:
      | { url?: string; imageUrl?: string; thumbnailUrl?: string }[]
      | {
          images?: { url?: string; imageUrl?: string; thumbnailUrl?: string }[];
        };
    images?: { url?: string; imageUrl?: string; thumbnailUrl?: string }[];
  };
  const rows = Array.isArray(data.data)
    ? data.data
    : (data.data && "images" in data.data ? data.data.images : undefined) ?? data.images ?? [];
  return rows
    .flatMap((row) => [row.imageUrl, row.url, row.thumbnailUrl])
    .filter((url): url is string => Boolean(url && /^https?:\/\//i.test(url)));
}

export async function firecrawlScrape(url: string): Promise<string> {
  return (await firecrawlScrapePage(url)).markdown;
}

export async function firecrawlScrapePage(
  url: string,
  opts: { images?: boolean; fullPage?: boolean } = {},
): Promise<ScrapePage> {
  const linkedin = /linkedin\.com/i.test(url);
  const data = (await firecrawlPost("/scrape", {
    url,
    formats: opts.images ? ["markdown", "images"] : ["markdown"],
    onlyMainContent: opts.fullPage ? false : true,
    waitFor: linkedin ? 2000 : undefined,
    proxy: linkedin ? "auto" : undefined,
  })) as {
    data?: {
      markdown?: string;
      content?: string;
      images?: unknown;
      metadata?: Record<string, unknown>;
    };
    markdown?: string;
    images?: unknown;
    metadata?: Record<string, unknown>;
  };
  const page = data.data ?? data;
  const metadata = page.metadata ?? {};
  const ogImage = firstString(
    metadata.ogImage,
    metadata["og:image"],
    metadata["og:image:secure_url"],
    metadata.og_image,
  );
  return {
    markdown: (page.markdown || page.content || "").trim(),
    images: collectImages(page.images),
    ogImage,
  };
}

function collectImages(raw: unknown): string[] {
  if (!raw) return [];
  if (typeof raw === "string") return /^https?:\/\//i.test(raw) ? [raw] : [];
  if (!Array.isArray(raw)) return [];
  return raw
    .flatMap((item) => {
      if (typeof item === "string") return [item];
      if (!item || typeof item !== "object") return [];
      const row = item as Record<string, unknown>;
      return [row.url, row.src, row.imageUrl].filter((value): value is string => typeof value === "string");
    })
    .filter((url) => /^https?:\/\//i.test(url));
}

function firstString(...values: unknown[]): string | undefined {
  for (const value of values) {
    if (typeof value === "string" && /^https?:\/\//i.test(value)) return value;
  }
  return undefined;
}

import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import type { FounderResearch, ResearchHit } from "../intelligence/types";
import { firecrawlImageSearch, firecrawlScrapePage } from "./firecrawl";
import { dirs } from "./paths";
import { assertInsideDeal } from "./sandbox";

export function founderSlug(name: string) {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "founder";
}

export function founderPhotoPath(dealId: string, name: string) {
  return `/api/deals/${dealId}/founder-photo?who=${encodeURIComponent(founderSlug(name))}`;
}

export function pickLinkedInPhoto(hits: ResearchHit[]): string | undefined {
  const pool = hits.flatMap((hit) => [
    ...(hit.images ?? []),
    hit.ogImage,
    ...urlsIn(hit.description),
  ]);
  return choosePhoto(pool);
}

export async function attachFounderPhotos(
  dealId: string,
  company: string,
  people: FounderResearch[],
): Promise<FounderResearch[]> {
  const out: FounderResearch[] = [];
  for (const person of people) {
    if (person.photoUrl) {
      out.push(person);
      continue;
    }
    const photoUrl = await findFounderPhoto(dealId, person.name, company, person.hits);
    out.push(photoUrl ? { ...person, photoUrl } : person);
  }
  return out;
}

async function findFounderPhoto(
  dealId: string,
  name: string,
  company: string,
  hits: ResearchHit[],
): Promise<string | undefined> {
  let remote = pickLinkedInPhoto(hits);
  if (!remote) {
    const profile = hits.find((hit) => /linkedin\.com\/in\//i.test(hit.url));
    if (profile) {
      try {
        const page = await firecrawlScrapePage(profile.url, { images: true, fullPage: true });
        remote = choosePhoto([page.ogImage, ...page.images, ...urlsIn(page.markdown)]);
      } catch {
        /* image search next */
      }
    }
  }
  if (!remote) {
    try {
      remote = choosePhoto(await firecrawlImageSearch(`"${name}" ${company} LinkedIn`, 8));
    } catch {
      return undefined;
    }
  }
  if (!remote) return undefined;
  return (await persistFounderPhoto(dealId, name, remote)) ?? remote;
}

async function persistFounderPhoto(dealId: string, name: string, remoteUrl: string): Promise<string | undefined> {
  try {
    const res = await fetch(remoteUrl, {
      redirect: "follow",
      headers: { "User-Agent": "Mozilla/5.0 Night Desk founder photo" },
    });
    if (!res.ok) return undefined;
    const type = res.headers.get("content-type") ?? "";
    const ext = extensionFor(type, remoteUrl);
    if (!ext) return undefined;
    const bytes = Buffer.from(await res.arrayBuffer());
    if (bytes.length < 800 || bytes.length > 2_500_000) return undefined;
    const folder = path.join(dirs().data, dealId, "founders");
    await mkdir(folder, { recursive: true });
    const file = assertInsideDeal(dealId, path.join(folder, `${founderSlug(name)}${ext}`));
    await writeFile(file, bytes);
    return founderPhotoPath(dealId, name);
  } catch {
    return undefined;
  }
}

function choosePhoto(urls: (string | undefined)[]): string | undefined {
  const scored = urls
    .filter((url): url is string => Boolean(url))
    .map((url) => ({ url, score: photoScore(url) }))
    .filter((row) => row.score > 0)
    .sort((a, b) => b.score - a.score);
  return scored[0]?.url;
}

function photoScore(url: string): number {
  const clean = url.split("?")[0] ?? url;
  if (/static\.licdn\.com|company-logo|hashtag|sprite|favicon|default-share/i.test(clean)) return 0;
  if (/profile-displaybackground|cover-photo/i.test(clean)) return 0;
  if (/media\.licdn\.com\/dms\/image/i.test(clean) && /profile-displayphoto|profile-framedphoto/i.test(clean)) {
    return 6;
  }
  if (/media\.licdn\.com\/dms\/image/i.test(clean)) return 4;
  if (/licdn\.com/i.test(clean) && /\.(jpe?g|png|webp)$/i.test(clean)) return 3;
  return 0;
}

function urlsIn(text: string): string[] {
  return text.match(/https?:\/\/[^\s)"'\]]+/g) ?? [];
}

function extensionFor(type: string, url: string): string | undefined {
  if (/image\/png/i.test(type)) return ".png";
  if (/image\/webp/i.test(type)) return ".webp";
  if (/image\/gif/i.test(type)) return ".gif";
  if (/image\/(jpeg|jpg)/i.test(type)) return ".jpg";
  const fromUrl = /\.(jpe?g|png|webp|gif)(?:$|\?)/i.exec(url)?.[1];
  if (fromUrl) return `.${fromUrl.toLowerCase().replace("jpeg", "jpg")}`;
  if (/^image\//i.test(type)) return ".jpg";
  return undefined;
}

