import { readFileSync } from "node:fs";
import { firecrawlImageSearch, firecrawlScrapePage } from "../lib/diligence/firecrawl";

const env = readFileSync(".env.local", "utf8");
for (const line of env.split("\n")) {
  const m = line.match(/^FIRECRAWL_API_KEY=(.+)$/);
  if (m) process.env.FIRECRAWL_API_KEY = m[1].trim().replace(/^["']|["']$/g, "");
}

function score(url: string) {
  const clean = url.split("?")[0] ?? url;
  if (/static\.licdn\.com|company-logo|hashtag|sprite|favicon|default-share/i.test(clean)) return 0;
  if (/profile-displaybackground|cover-photo/i.test(clean)) return 0;
  if (/media\.licdn\.com\/dms\/image/i.test(clean) && /profile-displayphoto|profile-framedphoto/i.test(clean)) return 6;
  if (/media\.licdn\.com\/dms\/image/i.test(clean)) return 4;
  if (/licdn\.com/i.test(clean) && /\.(jpe?g|png|webp)$/i.test(clean)) return 3;
  return 0;
}

async function main() {
  if (!process.env.FIRECRAWL_API_KEY) {
    console.log("NO_KEY");
    return;
  }
  try {
    const images = await firecrawlImageSearch('"Simon Kalouche" Nimble LinkedIn', 8);
    console.log(
      "IMAGE_SEARCH",
      images.length,
      images.slice(0, 8).map((u) => ({ score: score(u), host: new URL(u).host, path: u.slice(0, 140) })),
    );
  } catch (e) {
    console.log("IMAGE_SEARCH_FAIL", (e as Error).message.slice(0, 200));
  }
  try {
    const page = await firecrawlScrapePage("https://www.linkedin.com/in/simon-kalouche-98883343", {
      images: true,
      fullPage: true,
    });
    console.log("SCRAPE", {
      md: page.markdown.slice(0, 180),
      og: page.ogImage,
      images: page.images.slice(0, 10).map((u) => ({ score: score(u), url: u.slice(0, 160) })),
    });
  } catch (e) {
    console.log("SCRAPE_FAIL", (e as Error).message.slice(0, 200));
  }
}

main();

